    private val POLYS: Map<String, List<List<DoubleArray>>> by lazy {
        mapOf(
            "tottori" to decode(P_TOTTORI),
            "shimane" to decode(P_SHIMANE),
            "okayama" to decode(P_OKAYAMA),
            "hiroshima" to decode(P_HIROSHIMA),
            "yamaguchi" to decode(P_YAMAGUCHI),
        )
    }

    private fun decode(encoded: String): List<List<DoubleArray>> =
        encoded.split(";").map { poly ->
            poly.split("|").map { ring ->
                val nums = ring.split(" ").flatMap { it.split(",") }
                DoubleArray(nums.size) { i -> nums[i].toDouble() }
            }
        }

    /** 指定県の行政界内に含まれるか。データの無い県IDでは false (bbox方式へフォールバック)。 */
    fun contains(prefectureId: String, latitude: Double, longitude: Double): Boolean {
        val polys = POLYS[prefectureId] ?: return false
        for (poly in polys) {
            if (poly.isEmpty()) continue
            if (!pointInRing(poly[0], longitude, latitude)) continue
            var inHole = false
            for (i in 1 until poly.size) {
                if (pointInRing(poly[i], longitude, latitude)) {
                    inHole = true
                    break
                }
            }
            if (!inHole) return true
        }
        return false
    }

    /** ray casting (even-odd)。x=lon, y=lat。 */
    private fun pointInRing(ring: DoubleArray, x: Double, y: Double): Boolean {
        var inside = false
        var j = ring.size - 2
        var i = 0
        while (i < ring.size) {
            val xi = ring[i]
            val yi = ring[i + 1]
            val xj = ring[j]
            val yj = ring[j + 1]
            if ((yi > y) != (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) {
                inside = !inside
            }
            j = i
            i += 2
        }
        return inside
    }
}
